"use client";

import dynamic from "next/dynamic";
import type { MotionValue } from "motion";
import { motion, useScroll, useSpring, useTransform } from "motion/react";
import { useEffect, useRef, useState } from "react";

import { portfolioContent, type ProjectEntry } from "@/lib/content";
import { SCENE_PHASES, type SectionKey } from "@/lib/scene-config";

const SceneCanvas = dynamic(
  () => import("@/components/scene-canvas").then((module) => module.SceneCanvas),
  {
    ssr: false,
    loading: () => <div className="scene-placeholder" aria-hidden />,
  },
);

export function PortfolioExperience() {
  const shellRef = useRef<HTMLDivElement>(null);
  const { scrollYProgress } = useScroll({
    target: shellRef,
    offset: ["start start", "end end"],
  });
  const sceneProgress = useSpring(scrollYProgress, {
    stiffness: 120,
    damping: 24,
    mass: 0.24,
  });
  const meterScale = useTransform(sceneProgress, [0, 1], [0.08, 1]);
  const introBackdropOpacity = useTransform(
    sceneProgress,
    [0, 0.16, 0.28, 0.34],
    [1, 1, 0.18, 0],
  );

  return (
    <div className="portfolio-shell" ref={shellRef}>
      <motion.div
        className="intro-backdrop"
        aria-hidden
        style={{ opacity: introBackdropOpacity }}
      />

      <div className="scene-frame" aria-hidden>
        <SceneCanvas progress={sceneProgress} />
      </div>

      <div className="site-chrome">
        <a className="brand" href="#top">
          Anu
          <span>portfolio system</span>
        </a>

        <nav className="site-nav" aria-label="Section navigation">
          <a href="#project-01">Flux</a>
          <a href="#project-02">Signal</a>
          <a href="#project-03">Prism</a>
          <a href="#about">Approach</a>
          <a href="#contact">Contact</a>
        </nav>

        <div className="scroll-meter-shell" aria-hidden>
          <motion.span className="scroll-meter" style={{ scaleX: meterScale }} />
        </div>
      </div>

      <main className="page-stage" id="top">
        <IntroSection progress={sceneProgress} />
        <TransformSection />
        <HeroSection progress={sceneProgress} />
        <TransitionSection progress={sceneProgress} />

        {portfolioContent.projects.map((project, index) => (
          <ProjectSection
            key={project.slug}
            project={project}
            progress={sceneProgress}
            phaseKey={`project-${index + 1}` as SectionKey}
            align={index % 2 === 0 ? "left" : "right"}
          />
        ))}

        <AboutSection progress={sceneProgress} />
        <ContactSection progress={sceneProgress} />
      </main>
    </div>
  );
}

function IntroSection({ progress }: { progress: MotionValue<number> }) {
  const [isIntroNoteVisible, setIsIntroNoteVisible] = useState(false);
  const motionStyle = {
    opacity: useTransform(progress, [0, 0.12, 0.16], [1, 1, 0.28]),
    y: useTransform(progress, [0, 0.16], [0, -24]),
    scale: useTransform(progress, [0, 0.16], [1, 0.992]),
  };
  const introNoteStyle = {
    opacity: isIntroNoteVisible ? 1 : 0,
    y: useTransform(progress, [0, 0.16], [0, -18]),
  };

  useEffect(() => {
    const timeoutId = window.setTimeout(() => {
      setIsIntroNoteVisible(true);
    }, 1000);

    return () => {
      window.clearTimeout(timeoutId);
    };
  }, []);

  return (
    <section className="scroll-section scroll-section--intro" aria-label="Point cloud introduction">
      <div className="section-sticky section-sticky--intro">
        <motion.div className="intro-stage" style={motionStyle}>
          <div className="intro-copy">
            <p className="intro-title">
              <span>Hi, I'm</span>
              <span>Anurag</span>
            </p>
            <p className="intro-subtitle">
              a software engineer obsessed with building products that feel a little bit
              magical
            </p>
            <div className="intro-prompt">
              <span className="intro-prompt__label">Scroll to enter</span>
            </div>
          </div>

          <motion.div className="intro-note" style={introNoteStyle}>
            <p className="intro-note__text">(yep, that&apos;s a real LIDAR scan of my head)</p>
          </motion.div>
        </motion.div>
      </div>
    </section>
  );
}

function TransformSection() {
  return (
    <section
      className="scroll-section scroll-section--transform"
      aria-hidden="true"
    >
      <div className="section-sticky section-sticky--center">
        <div className="transform-stage" />
      </div>
    </section>
  );
}

function HeroSection({ progress }: { progress: MotionValue<number> }) {
  const motionStyle = useSectionMotion(progress, "hero");

  return (
    <section className="scroll-section scroll-section--hero" aria-labelledby="hero-title">
      <div className="section-anchor" id="hero" />
      <div className="section-sticky">
        <motion.article className="panel panel--hero" style={motionStyle}>
          <span className="eyebrow">{portfolioContent.hero.eyebrow}</span>
          <h1 id="hero-title">{portfolioContent.hero.title}</h1>
          <div className="panel-copy hero-copy">
            <p>{portfolioContent.hero.body}</p>
          </div>
          <div className="hero-footer">
            {portfolioContent.hero.facts.map((fact) => (
              <span className="metric-pill" key={fact.label}>
                {fact.label}
                <strong>{fact.value}</strong>
              </span>
            ))}
          </div>
        </motion.article>
      </div>
    </section>
  );
}

function TransitionSection({ progress }: { progress: MotionValue<number> }) {
  const motionStyle = useSectionMotion(progress, "reveal");

  return (
    <section className="scroll-section scroll-section--compact" aria-labelledby="transition-title">
      <div className="section-sticky section-sticky--center">
        <motion.article className="panel panel--center panel--compact" style={motionStyle}>
          <span className="eyebrow">{portfolioContent.transition.eyebrow}</span>
          <h2 id="transition-title">{portfolioContent.transition.title}</h2>
          <div className="panel-copy transition-copy">
            <p>{portfolioContent.transition.body}</p>
          </div>
        </motion.article>
      </div>
    </section>
  );
}

function ProjectSection({
  project,
  progress,
  phaseKey,
  align,
}: {
  project: ProjectEntry;
  progress: MotionValue<number>;
  phaseKey: SectionKey;
  align: "left" | "right";
}) {
  const motionStyle = useSectionMotion(progress, phaseKey);

  return (
    <section className="scroll-section" id={project.slug} aria-labelledby={`${project.slug}-title`}>
      <div className="section-sticky">
        <motion.article
          className={`panel ${align === "right" ? "panel--right" : ""}`}
          style={motionStyle}
        >
          <div className="project-headline">
            <span className="eyebrow">{project.eyebrow}</span>
            <h2 id={`${project.slug}-title`}>{project.title}</h2>
            <p>{project.summary}</p>
          </div>

          <div className="project-meta">
            <span className="metric-pill">
              Role
              <strong>{project.role}</strong>
            </span>
            <span className="metric-pill">
              Year
              <strong>{project.year}</strong>
            </span>
          </div>

          <div className="panel-copy project-grid">
            <div className="project-body">
              <p>{project.outcome}</p>
              {project.description.map((paragraph) => (
                <p key={paragraph}>{paragraph}</p>
              ))}
            </div>

            <div className="project-metrics" aria-label="Project outcomes">
              {project.metrics.map((metric) => (
                <span className="project-stat" key={metric}>
                  Outcome
                  <strong>{metric}</strong>
                </span>
              ))}
            </div>

            <div className="project-tags" aria-label="Project tags">
              {project.tags.map((tag) => (
                <span className="tag" key={tag}>
                  {tag}
                </span>
              ))}
            </div>
          </div>
        </motion.article>
      </div>
    </section>
  );
}

function AboutSection({ progress }: { progress: MotionValue<number> }) {
  const motionStyle = useSectionMotion(progress, "about");

  return (
    <section className="scroll-section scroll-section--compact" id="about" aria-labelledby="about-title">
      <div className="section-sticky">
        <motion.article className="panel panel--compact" style={motionStyle}>
          <span className="eyebrow">{portfolioContent.about.eyebrow}</span>
          <h2 id="about-title">{portfolioContent.about.title}</h2>
          <div className="panel-copy">
            {portfolioContent.about.paragraphs.map((paragraph) => (
              <p key={paragraph}>{paragraph}</p>
            ))}
          </div>
        </motion.article>
      </div>
    </section>
  );
}

function ContactSection({ progress }: { progress: MotionValue<number> }) {
  const motionStyle = useSectionMotion(progress, "contact");

  return (
    <section
      className="scroll-section scroll-section--compact"
      id="contact"
      aria-labelledby="contact-title"
    >
      <div className="section-sticky section-sticky--center">
        <motion.article className="panel contact-panel" style={motionStyle}>
          <span className="eyebrow">{portfolioContent.contact.eyebrow}</span>
          <h2 id="contact-title">{portfolioContent.contact.title}</h2>
          <div className="panel-copy">
            <p>{portfolioContent.contact.body}</p>
          </div>
          <div className="contact-actions">
            <a className="cta-link" href={`mailto:${portfolioContent.contact.email}`}>
              {portfolioContent.contact.email}
            </a>
            <a
              className="cta-link"
              href={portfolioContent.contact.secondaryHref}
              rel="noreferrer"
              target="_blank"
            >
              {portfolioContent.contact.secondaryLabel}
            </a>
          </div>
          <p className="footer-note">Placeholder contact details. Replace with live links.</p>
        </motion.article>
      </div>
    </section>
  );
}

function useSectionMotion(progress: MotionValue<number>, phaseKey: SectionKey) {
  const phase = SCENE_PHASES.find((entry) => entry.key === phaseKey) ?? SCENE_PHASES[0];
  const opacity = useTransform(
    progress,
    [phase.range[0], phase.range[0] + 0.04, phase.range[1] - 0.05, phase.range[1]],
    [0.16, 1, 1, 0.22],
  );
  const y = useTransform(progress, [phase.range[0], phase.range[1]], [44, -30]);
  const scale = useTransform(
    progress,
    [phase.range[0], phase.range[0] + 0.08, phase.range[1]],
    [0.98, 1, 0.992],
  );

  return { opacity, y, scale };
}
